{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_Ajio_margin_fact_items as SELECT COALESCE(B.EAN,REPLACE(REPLACE(A.EANUPC, \'`\', \'\'), \',\', \'\')) EAN, A.SKU, A.GENDER, UPPER(A.CATEGORY_NAME) CATEGORY_NAME, A.SAP_CATEGORY, UPPER(A.TYPE) TYPE, UPPER(A.LEVEL) LEVEL, A.FLIPKART_CATEGORY CATEGORY, AVAILABLE_QUANTITY, 77.0 AS \"DISCOUNT_%\", CASE WHEN COALESCE(RF.\"Courier Return %\", RA.\"Courier Return %\") IS NULL OR COALESCE(RF.\"Courier Return %\", RA.\"Courier Return %\") = 0 THEN 25 ELSE ROUND(COALESCE(RF.\"Courier Return %\", RA.\"Courier Return %\"), 1) END AS \"COURIER_RET%\", CASE WHEN COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\") IS NULL OR COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\") = 0 THEN 11 ELSE ROUND(COALESCE(RF.\"Customer Return %\",RA.\"Customer Return %\"), 1)END AS \"CUSTOMER_RET%\", CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, ROUND(COALESCE(MRP,0) / NULLIF(COST, 0),2) AS MULTIPLE, ROUND(COALESCE(MRP,0) - (COALESCE(MRP,0) * \"DISCOUNT_%\" / 100),2) AS BILL_VALUE, CASE WHEN BILL_VALUE < 2625 THEN 5 ELSE 18 END AS \"GST_%\", ROUND((BILL_VALUE * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE, ROUND(COALESCE(COMMISSION,0),2) \"AJIO_MARGIN%\", COALESCE(ROUND(CASE WHEN BILL_VALUE * (NULLIF(\"AJIO_MARGIN%\",0)/100) < 200 THEN 200 ELSE BILL_VALUE * (NULLIF(\"AJIO_MARGIN%\",0)/100) END, 2), 0) AS AJIO_MARGIN_VALUE, COALESCE(COALESCE(SALE_VALUE,0) - COALESCE(AJIO_MARGIN_VALUE,0),0) AS PO_VALUE, COALESCE(ROUND(5 / NULLIF((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\") / 100, 0), 2), 0) AS PACKING, ROUND(SALE_VALUE *(2/100),2) ADVT, ROUND(PO_VALUE *(7.5/100),2) COMMON, ROUND(COALESCE(PACKING,0) + COALESCE(ADVT,0) + COALESCE(COMMON,0),2) AS TOTAL_EXPENSES, COALESCE((TOTAL_EXPENSES / NULLIF(PO_VALUE,0)),0) AS \"EXPENSES%\", COALESCE((PO_VALUE - COST - TOTAL_EXPENSES),0) AS NET_MARGIN, ROUND((NET_MARGIN/NULLIF(PO_VALUE,0)*100),2) \"NET_MARGIN%\" FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN ( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE, REPLACE(EAN, \'`\', \'\') AS EAN, SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( SELECT DISTINCT UPPER(\"SAP Category\") SAP_CATEGORY ,COMMISSION FROM MAPLEMONK.REDTAPE_AJIO_MARGIN_COMMISSION )MC ON UPPER(TRIM(A.SAP_CATEGORY)) = UPPER(TRIM(MC.SAP_CATEGORY)) LEFT JOIN ( SELECT CATEGORY_NAME ,TYPE ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_AJIO_MARGIN_RETURN_FOOTWEAR WHERE UPPER(GENDER) != \'ALL\') RF ON UPPER(TRIM(A.CATEGORY_NAME)) = UPPER(TRIM(RF.CATEGORY_NAME)) AND UPPER(TRIM(A.TYPE)) = UPPER(TRIM(RF.TYPE)) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(RF.GENDER)) LEFT JOIN( SELECT CATEGORY_NAME ,SAP_CATEGORY ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_AJIO_MARGIN_RETURN_APARELS WHERE UPPER(GENDER) != \'ALL\') RA ON UPPER(TRIM(A.CATEGORY_NAME)) = UPPER(TRIM(RA.CATEGORY_NAME)) AND UPPER(TRIM(A.SAP_CATEGORY)) = UPPER(TRIM(RA.SAP_CATEGORY)) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(RA.GENDER)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            